#!/usr/bin/env bash
set -euo pipefail
GSZ=/opt/gsz
A="$GSZ/routes/account.js"; B="$GSZ/views/account/dashboard.ejs"
TS=$(date +%Y%m%d-%H%M%S)
echo "==> step188: product-aware Quick Actions (hide Netflix if none; add IPTV renewal action)"
for F in "$A" "$B"; do cp "$F" "$F.bak-step188-$TS"; done
echo "    backups: *.bak-step188-$TS"
restore(){ echo "!! restoring"; for F in "$A" "$B"; do cp "$F.bak-step188-$TS" "$F" 2>/dev/null||true; done; }
trap 'restore' ERR
P=$(mktemp /tmp/p188.XXXXXX.js); echo "" | base64 -d > "$P"
echo "==> applying"; NODE_PATH="$GSZ/node_modules" node "$P" "$GSZ"
echo "==> validating"
NODE_PATH="$GSZ/node_modules" node --check "$A" && echo "    account.js ok"
NODE_PATH="$GSZ/node_modules" node -e "const ejs=require('ejs'),fs=require('fs');ejs.compile(fs.readFileSync('$B','utf8'),{filename:'$B'});console.log('    dashboard.ejs ok')"
echo "==> restarting"; pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz
CODE=000; for i in $(seq 1 25); do sleep 1; CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || echo 000); [ "$CODE" = "200" ] && break; done
[ "$CODE" = "200" ] || { echo "    homepage $CODE"; false; }
echo "    homepage 200: OK (after ${i}s)"
rm -f "$P"; trap - ERR
echo ""
echo "==> step188 OK  Account Quick Actions are now product-aware: 'Netflix codes' shows only for Netflix owners, and an 'My IPTV & renewal' action appears for customers with an IPTV line (opens its live expiry/renew card)."
